using System.IO;
using System.Data;
using DocumentFormat.OpenXml;
using DocumentFormat.OpenXml.Packaging;
using DocumentFormat.OpenXml.Spreadsheet;
using DocumentFormat.OpenXml.Validation;
namespace Hisab;
public static class ItemImportTests
{
    public static ItemImportInput Input(string code="XL-001",string qty="2",string cost="50")=>new(2,code,"Laptop / حاسوب","Stock","100","001234",qty,cost,"No","");
    public static string Fixture(string directory,string name,params ItemImportInput[] rows)
    {
        string path=Path.Combine(directory,name+".xlsx");ExcelWorkbook.WriteTemplate(path);using var book=SpreadsheetDocument.Open(path,true);var sheet=book.WorkbookPart!.WorksheetParts.Single().Worksheet!;var data=sheet.GetFirstChild<SheetData>()!;
        foreach(var input in rows){var row=new Row{RowIndex=(uint)input.Row};var values=new[]{input.Code,input.Name,input.Type,input.Price,input.Barcode,input.Quantity,input.Cost,input.Serialized,input.Serials};for(int i=0;i<values.Length;i++)if(values[i].Length>0)row.Append(new Cell{CellReference=ExcelWorkbook.ColumnName(i)+input.Row,DataType=CellValues.InlineString,InlineString=new InlineString(new Text(values[i]))});data.Append(row);}sheet.Save();return path;
    }
    public static Dictionary<string,int> Mapping()=>ItemImportMapping.Fields.Select((f,i)=>(f,i)).ToDictionary(x=>x.f,x=>x.i);
    public static void Run(string directory,List<string> results)
    {
        void Check(bool ok,string name){if(!ok)throw new Exception(name);results.Add("PASS "+name);}
        void Reject(Action action,string name){try{action();}catch(InvalidOperationException){results.Add("PASS "+name);return;}throw new Exception("Expected rejection: "+name);}
        using var s=new Store(Path.Combine(directory,"import-"+Guid.NewGuid()+".db"));var a=new AccountingService(s);var today=DateTime.Today;
        var good=Input("00017") with {Serialized="Yes",Serials="0001\n0002"};string path=Fixture(directory,"import-fixture",good);
        using(var book=SpreadsheetDocument.Open(path,false))Check(!new OpenXmlValidator().Validate(book).Any(),"Excel template and populated workbook conform to Open XML");
        var sheet=ExcelWorkbook.Read(path).Single();var input=ItemImportMapping.Read(sheet,1,Mapping());Check(input.Single().Code=="00017"&&input.Single().Barcode=="001234"&&input.Single().Serials=="0001\n0002","Excel import preserves text identifiers Arabic and leading zeros");
        long auditBefore=Convert.ToInt64(s.Scalar("SELECT count(*) FROM audit"));int before=s.Items().Count;var plan=a.PreviewItemImport(input,today,1);Check(plan.CanImport&&plan.OpeningValue==100&&s.Items().Count==before&&auditBefore==Convert.ToInt64(s.Scalar("SELECT count(*) FROM audit")),"Excel preview is read only and reports exact opening value");
        Check(a.CommitItemImport(plan,path)==1,"Reviewed Excel batch imports successfully");var imported=s.Items().Single(i=>i.Code=="00017");Check(imported.Qty==2000&&imported.Value==100000&&s.AvailableSerials(imported.Id,1).SequenceEqual(new[]{"0001","0002"}),"Excel opening stock preserves valuation and serial identities");Check(s.Balance(s.AccountId("1301"))==100000&&s.Table("PRAGMA foreign_key_check").Rows.Count==0,"Excel import posts balanced inventory with valid relationships");
        Reject(()=>a.CommitItemImport(plan,path),"A reviewed batch cannot be committed twice");var repeat=a.PreviewItemImport(input,today,1);Check(!repeat.CanImport&&repeat.Rows.Single().Action=="Skip","Reimport defaults to skipping existing codes");
        Check(a.PreviewItemImport(input,today,1,true).Rows.Single().Action=="Error","Existing stock movements prevent a second opening balance");
        var unused=s.Items().First(i=>i.Code!="00017");var opening=Input(unused.Code) with {Name="Do not overwrite",Price="999",Barcode="DIFFERENT"};var existing=a.PreviewItemImport([opening],today,1,true);Check(existing.CanImport&&existing.Rows.Single().Action=="Opening","Existing unused items can explicitly receive opening stock");a.CommitItemImport(existing,path);Check(s.Items().Single(i=>i.Id==unused.Id).Name==unused.Name&&s.Items().Single(i=>i.Id==unused.Id).Price==unused.Price,"Existing item details stay unchanged during opening import");
        ItemImportPlan Preview(ItemImportInput row)=>a.PreviewItemImport([row],today,1);
        var fresh=Input("FRESH") with {Barcode=""};Check(a.PreviewItemImport([fresh,fresh with {Row=3,Code="fresh"}],today,1).Rows.All(r=>r.Action=="Error"),"Duplicate file codes are rejected without case sensitivity");
        Check(a.PreviewItemImport([fresh with {Barcode="X"},fresh with {Row=3,Code="OTHER",Barcode="x"}],today,1).Rows.All(r=>r.Action=="Error"),"Duplicate file barcodes are rejected");
        Check(Preview(fresh with {Barcode="001234"}).Rows.Single().Action=="Error","Existing barcodes cannot be assigned to new products");
        foreach(var pair in new[]{(fresh with {Quantity="-1"},"Negative opening quantity"),(fresh with {Quantity="1.0001"},"Excess quantity precision"),(fresh with {Cost="0"},"Zero opening cost"),(fresh with {Type="Service"},"Service stock quantity"),(fresh with {Serialized="Yes",Serials="S1,S1"},"Duplicate serials"),(fresh with {Serialized="Yes",Quantity="1.5",Serials="S1"},"Fractional serialized quantity"),(fresh with {Serials="S1,S2"},"Serials without tracking"),(fresh with {Price="abc"},"Malformed price"),(fresh with {Type="unknown"},"Unknown item type")})Check(Preview(pair.Item1).Rows.Single().Action=="Error",pair.Item2+" is flagged in preview");
        Check(a.PreviewItemImport([fresh],today.AddDays(1),1).Rows.Single().Action=="Error","Future opening date is rejected in preview");
        var stale=Preview(fresh);s.SaveItem(null,"FRESH","Created while reviewing",true,0);Reject(()=>a.CommitItemImport(stale,path),"Database changes invalidate stale import previews");
        var first=Input("ROLL-1") with {Barcode=""};var second=first with {Row=3,Code="ROLL-2"};var rollback=a.PreviewItemImport([first,second],today,1);long docs=Convert.ToInt64(s.Scalar("SELECT count(*) FROM documents")),audits=Convert.ToInt64(s.Scalar("SELECT count(*) FROM audit"));s.Exec("CREATE TRIGGER reject_import BEFORE INSERT ON items WHEN NEW.code='ROLL-2' BEGIN SELECT RAISE(ABORT,'test failure'); END");bool failed=false;try{a.CommitItemImport(rollback,path);}catch(Microsoft.Data.Sqlite.SqliteException){failed=true;}s.Exec("DROP TRIGGER reject_import");Check(failed&&!s.Items().Any(i=>i.Code.StartsWith("ROLL-"))&&docs==Convert.ToInt64(s.Scalar("SELECT count(*) FROM documents"))&&audits==Convert.ToInt64(s.Scalar("SELECT count(*) FROM audit")),"Unexpected batch failure rolls back products stock journals and audit");
        var service=Input("SERVICE","0","0") with {Type="Service",Barcode="",Price="12.500"};Check(Preview(service).CanImport,"Product-only and service imports need no opening stock");
        string cells=Fixture(directory,"cell-types",Input("TEXT") with {Row=5,Barcode=""});using(var book=SpreadsheetDocument.Open(cells,true)){var wb=book.WorkbookPart!;var shared=wb.AddNewPart<SharedStringTablePart>();shared.SharedStringTable=new SharedStringTable(new SharedStringItem(new Text("اسم من Excel")));var data=wb.WorksheetParts.Single().Worksheet!.GetFirstChild<SheetData>()!;var row=data.Elements<Row>().Single(r=>r.RowIndex?.Value==5);row.Hidden=true;var name=row.Elements<Cell>().Single(c=>c.CellReference=="B5");name.RemoveAllChildren();name.DataType=CellValues.SharedString;name.CellValue=new CellValue("0");var price=row.Elements<Cell>().Single(c=>c.CellReference=="D5");price.RemoveAllChildren();price.DataType=CellValues.Number;price.CellValue=new CellValue("1E2");wb.WorksheetParts.Single().Worksheet!.Save();}
        var parsed=ItemImportMapping.Read(ExcelWorkbook.Read(cells).Single(),1,Mapping()).Single();Check(parsed.Row==5&&parsed.Name=="اسم من Excel"&&parsed.Price=="100","Excel reader handles shared strings sparse rows hidden rows and numeric exponents");
        using(var book=SpreadsheetDocument.Open(cells,true)){var cell=book.WorkbookPart!.WorksheetParts.Single().Worksheet!.Descendants<Cell>().Single(c=>c.CellReference=="A5");cell.RemoveAllChildren();cell.DataType=CellValues.Number;cell.CellValue=new CellValue("17");}
        Check(ItemImportMapping.Read(ExcelWorkbook.Read(cells).Single(),1,Mapping()).Single().Error.Contains("Code"),"Numeric identifiers require text conversion before import");
        using(var book=SpreadsheetDocument.Open(cells,true)){var cell=book.WorkbookPart!.WorksheetParts.Single().Worksheet!.Descendants<Cell>().Single(c=>c.CellReference=="D5");cell.CellFormula=new CellFormula("1+1");}
        Check(ItemImportMapping.Read(ExcelWorkbook.Read(cells).Single(),1,Mapping()).Single().Error.Contains("formulas"),"Formula cells cannot silently import stale cached values");
        var map=Mapping();map["Name"]=0;Reject(()=>ItemImportMapping.Read(sheet,1,map),"Multiple fields cannot use the same mapped column");
        Reject(()=>ExcelWorkbook.Read(Path.Combine(directory,"legacy.xls")),"Legacy Excel formats receive an explicit conversion message");
        using(var book=SpreadsheetDocument.Open(cells,true)){book.WorkbookPart!.WorksheetParts.Single().Worksheet!.Append(new MergeCells(new MergeCell{Reference="A1:B1"}));}Reject(()=>ItemImportMapping.Read(ExcelWorkbook.Read(cells).Single(),1,Mapping()),"Merged import cells are rejected instead of silently dropping values");

        var countItem=s.Items().First(i=>i.Qty==0&&i.Stock&&i.Code!="FRESH");long count=a.StartStockCount(1,[countItem.Id]);Check(a.PreviewItemImport([fresh with {Code=countItem.Code}],today,1,true).Rows.Single().Action=="Error","Open stock counts block existing-item opening imports");a.CancelStockCount(count);
        long inactive=s.SaveLocation(null,"Inactive import location");s.SaveLocation(inactive,"Inactive import location",false);Check(a.PreviewItemImport([fresh with {Code="INACTIVE"}],today,inactive).Rows.Single().Action=="Error","Inactive locations cannot receive imported opening stock");
        long closing=Convert.ToInt64(s.Scalar("SELECT id FROM documents LIMIT 1"));s.Exec("INSERT INTO periods(start,end,closing_doc) VALUES(@p0,@p1,@p2)",today.AddDays(-1).ToString("yyyy-MM-dd"),today.ToString("yyyy-MM-dd"),closing);Check(a.PreviewItemImport([fresh with {Code="CLOSED"}],today,1).Rows.Single().Action=="Error","Closed accounting periods are flagged before importing stock");Check(a.PreviewItemImport([fresh with {Code="CLOSED-SERIAL",Quantity="0",Cost="0",Serialized="Yes"}],today,1).Rows.Single().Action=="Error","Serialized item registration respects closed periods without opening stock");s.Exec("DELETE FROM periods WHERE closing_doc=@p0",closing);
        string dates=Fixture(directory,"date-cell",fresh);using(var book=SpreadsheetDocument.Open(dates,true)){var wb=book.WorkbookPart!;var formats=wb.WorkbookStylesPart!.Stylesheet!.CellFormats!;formats.Append(new CellFormat{NumberFormatId=14,ApplyNumberFormat=true});var c=wb.WorksheetParts.Single().Worksheet!.Descendants<Cell>().Single(c=>c.CellReference=="F2");c.RemoveAllChildren();c.DataType=CellValues.Number;c.CellValue=new CellValue("46000");c.StyleIndex=2;}
        Check(ItemImportMapping.Read(ExcelWorkbook.Read(dates).Single(),1,Mapping()).Single().Error.Contains("date"),"Excel date-formatted quantities cannot be mistaken for stock counts");
        s.SaveUser("import-viewer","import-viewer-password","Viewer");s.Login("import-viewer","import-viewer-password");Reject(()=>a.PreviewItemImport([fresh],today,1),"Viewer cannot preview privileged item imports");Reject(()=>a.CommitItemImport(plan,path),"Viewer cannot commit an item import");
    }
}
